import{_ as e,c as r,o as t,ag as l}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"服務條款","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/terms.md","filePath":"zh-TW/guide/terms.md","lastUpdated":1791311600000}'),i={name:"zh-TW/guide/terms.md"};function h(o,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="服務條款" tabindex="-1">服務條款 <a class="header-anchor" href="#服務條款" aria-label="Permalink to &quot;服務條款&quot;">​</a></h1><p>本條款約束你對 nPlyr 的使用。下載、安裝或使用 nPlyr，即表示你同意本條款。如果你不同意，請勿使用該應用程式。</p><h2 id="許可與使用" tabindex="-1">許可與使用 <a class="header-anchor" href="#許可與使用" aria-label="Permalink to &quot;許可與使用&quot;">​</a></h2><p>nPlyr 按照每個發布版本隨附的許可條款提供。你被授予一項有限的、非獨佔的、不可轉讓的許可，可在你的 Mac 上依據許可條款使用本應用程式。</p><h2 id="本機優先執行" tabindex="-1">本機優先執行 <a class="header-anchor" href="#本機優先執行" aria-label="Permalink to &quot;本機優先執行&quot;">​</a></h2><p>nPlyr 在你的裝置上本機執行，用於媒體播放、下載與裝置端功能。你的觀看歷程、書籤與下載內容不會被傳輸到我們的伺服器。應用程式不營運收集你的媒體或使用資料的後端。</p><h2 id="網路使用" tabindex="-1">網路使用 <a class="header-anchor" href="#網路使用" aria-label="Permalink to &quot;網路使用&quot;">​</a></h2><p>nPlyr 僅在串流媒體、下載、使用內建嗅探器瀏覽，或執行你選擇匯入的小程式 / 規則來源時存取網路。你有責任遵守所存取網站與來源的條款。</p><h2 id="第三方內容" tabindex="-1">第三方內容 <a class="header-anchor" href="#第三方內容" aria-label="Permalink to &quot;第三方內容&quot;">​</a></h2><p>小程式與規則來源由社群提供，而非由 nPlyr 提供。nPlyr 對其內容、可用性或不為其做法承擔責任。只安裝你信任的來源。</p><h2 id="購買" tabindex="-1">購買 <a class="header-anchor" href="#購買" aria-label="Permalink to &quot;購買&quot;">​</a></h2><p>完整功能許可（若提供）可透過 Mac App Store 取得。所有購買均由 Apple 處理。nPlyr 不處理支付資訊。重新安裝時支援購買恢復。</p><h2 id="使用者責任" tabindex="-1">使用者責任 <a class="header-anchor" href="#使用者責任" aria-label="Permalink to &quot;使用者責任&quot;">​</a></h2><ul><li>合法使用 nPlyr，並遵守適用規則。</li><li>不要試圖反編譯、逆向工程或以違反許可的方式修改應用程式。</li><li>你有責任遵守你所傳送的第三方內容的相關可接受使用政策。</li></ul><h2 id="隱私" tabindex="-1">隱私 <a class="header-anchor" href="#隱私" aria-label="Permalink to &quot;隱私&quot;">​</a></h2><p>請查閱<a href="/zh-TW/guide/privacy.html">隱私政策</a>了解資料實踐與隱私相關資訊。</p><h2 id="免責聲明" tabindex="-1">免責聲明 <a class="header-anchor" href="#免責聲明" aria-label="Permalink to &quot;免責聲明&quot;">​</a></h2><p>nPlyr 按「原樣」提供，不附帶任何種類的擔保。在適用法律允許的最大範圍內，維護者放棄所有明示、默示、法定或其他形式的擔保，包括適銷性與特定用途適用性。</p><h2 id="責任限制" tabindex="-1">責任限制 <a class="header-anchor" href="#責任限制" aria-label="Permalink to &quot;責任限制&quot;">​</a></h2><p>在適用法律允許的最大範圍內，維護者不對因你使用本應用程式而引起的任何間接、附帶、特殊、後果性或懲罰性損害承擔責任。</p><h2 id="終止" tabindex="-1">終止 <a class="header-anchor" href="#終止" aria-label="Permalink to &quot;終止&quot;">​</a></h2><p>如果你未能遵守本條款，授予你的權利將自動終止。</p><h2 id="變更" tabindex="-1">變更 <a class="header-anchor" href="#變更" aria-label="Permalink to &quot;變更&quot;">​</a></h2><p>我們可能不時更新本條款。變更後繼續使用即構成對修訂後條款的接受。</p><h2 id="聯絡" tabindex="-1">聯絡 <a class="header-anchor" href="#聯絡" aria-label="Permalink to &quot;聯絡&quot;">​</a></h2><p>如果你對本條款有疑問，請在專案倉庫提交 issue： <code>https://github.com/nPlyr/nPlyr-site/issues</code></p><p>或透過電子郵件聯絡我們：nPlyr@w3cub.com</p><p><em>最後更新：2026 年 8 月 5 日</em></p>',28)])])}const m=e(i,[["render",h]]);export{u as __pageData,m as default};
